[asy]
real f(real x)
{

return x/2;
}

import graph;
size(6cm);
real a = 8;
pair A=(-a,a), B=(a,a), C=(a,-a), D=(-a,-a);
draw(A--B--C--D--cycle);
draw(graph(f,-11,11),Arrows);
axes(Arrows(4));
